def decode_value(meta,k,v):
    f=meta.get(k)
    if not f or v is None:
        return v
    opts={o['id']:o.get('label') for o in (f.get('options') or [])}
    t=f.get('field_type')
    if t=='set' and isinstance(v,str):
        ids=[int(x) for x in v.split(',') if x]
        return [opts.get(i,i) for i in ids]
    if t=='enum':
        try:
            i=int(v)
        except Exception:
            return v
        return opts.get(i,i)
    return v
